mapper.select:
select SEQNO,busiDate,startTime,endTime,status,detailAction,taskCname,lastTime from ( SELECT LOG.SEQNO,DATE_FORMAT(LOG.BUSI_DATE,'%Y%m%d') busiDate,LOG.START_TIME startTime,LOG.END_TIME endTime ,(case when LOG.STATUS = '02' then (case when IFNULL( logDetail.ERROR, 0 ) = 0 then '02' else '09' end) else LOG.STATUS end) status ,(case when ILOG.STATUS = '02' then (case when IFNULL ( logDetail.ERROR, 0 ) = 0 then concat_ws('','执行成功', IFNULL ( logDetail.success, 0 ),'条') else concat_ws('','执行成功',IFNULL ( logDetail.success, 0 ),'条,失败',IFNULL ( logDetail.ERROR, 0 ),'条') end) else LOG.DETAIL_ACTION end) detailAction1 ,ta.TASK_NAME taskCname,ROUND(LOG.LAST_TIME/1000,2) lastTime ,LOG.EXEC_RESULT detailAction FROM VAL_INTERF_ACTIONLOG LOG left join VAL_INTERF_TASK ta on ta.BEAN_NAME=LOG.TASK_ENAME LEFT JOIN( SELECT a.parent_seqno,sum(a.success) success,sum(a.ERROR) ERROR FROM ( SELECT parent_seqno parent_seqno, (case when VAL.IS_CHECK = 'Y' then LENGHT end) success, (case when VAL.IS_CHECK = 'N' then LENGHT end) ERROR from ( SELECT parent_seqno,IS_CHECK,COUNT(1) LENGHT FROM VAL_INTERFLOG WHERE 1=1 group by parent_seqno,IS_CHECK) val) a group by parent_seqno
) logDetail ON LOG.Seqno=logDetail.parent_seqno WHERE 1=1
AND LOG.EXECTASK_SEQNO = #{execTaskId} ) logdetail WHERE 1=1
AND logdetail.status = #{status}
ORDER BY busiDate
